-- DizzyOps PostgreSQL baseline schema (not yet deployed)
-- Run only after authentication and tenant access policy review.
create extension if not exists pgcrypto;
create table if not exists organizations(id uuid primary key default gen_random_uuid(),name text not null,created_at timestamptz not null default now());
create table if not exists app_users(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),external_subject text, email text not null,display_name text not null,account_type text not null check(account_type in ('staff','performer','contractor')),active boolean not null default true,created_at timestamptz not null default now(),unique(organization_id,email));
create table if not exists app_roles(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),name text not null,unique(organization_id,name));
create table if not exists user_roles(user_id uuid not null references app_users(id) on delete cascade,role_id uuid not null references app_roles(id) on delete cascade,primary key(user_id,role_id));
create table if not exists clients(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),name text not null,email text,phone text,created_at timestamptz not null default now());
create table if not exists performers(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),user_id uuid unique references app_users(id),stage_name text not null,category text,availability_status text not null default 'unknown',created_at timestamptz not null default now());
create table if not exists performer_skills(performer_id uuid not null references performers(id) on delete cascade,skill text not null,primary key(performer_id,skill));
create table if not exists contractors(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),name text not null,service_type text,contact_email text,created_at timestamptz not null default now());
create table if not exists bookings(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),client_id uuid references clients(id),title text not null,status text not null default 'enquiry',starts_at timestamptz,ends_at timestamptz,venue text,created_at timestamptz not null default now(),constraint booking_time_check check(ends_at is null or starts_at is null or ends_at>starts_at));
create table if not exists booking_assignments(id uuid primary key default gen_random_uuid(),booking_id uuid not null references bookings(id) on delete cascade,performer_id uuid not null references performers(id),status text not null default 'invited',unique(booking_id,performer_id));
create table if not exists invoices(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),booking_id uuid references bookings(id),invoice_number text not null,currency char(3) not null default 'ZAR',total_amount numeric(14,2) not null default 0,status text not null default 'draft',issued_at timestamptz,due_at timestamptz,unique(organization_id,invoice_number));
create table if not exists payments(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),invoice_id uuid not null references invoices(id),amount numeric(14,2) not null check(amount>0),paid_at timestamptz not null default now(),reference text);
create table if not exists expenses(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),booking_id uuid references bookings(id),description text not null,amount numeric(14,2) not null check(amount>=0),status text not null default 'pending',created_at timestamptz not null default now());
create table if not exists assets(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),name text not null,category text,quantity integer not null default 1 check(quantity>=0),created_at timestamptz not null default now());
create table if not exists audit_events(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),actor_id uuid references app_users(id),entity_type text not null,entity_id uuid,action text not null,details jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index if not exists idx_bookings_org_start on bookings(organization_id,starts_at);
create index if not exists idx_performers_org on performers(organization_id);
create index if not exists idx_invoices_org_status on invoices(organization_id,status);
-- SECURITY GATE: enable RLS before connecting any client-facing API.
-- These tables intentionally have no anonymous access policies.
do $$ declare t text; begin foreach t in array array['organizations','app_users','app_roles','user_roles','clients','performers','performer_skills','contractors','bookings','booking_assignments','invoices','payments','expenses','assets','audit_events'] loop execute format('alter table %I enable row level security',t); end loop; end $$;
